INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (1, 'shock-absorber', 'Shock Absorber (Peredam Kejut)', 'Shock absorber / damper', 'peredam', 'Meredam ayunan pegas agar roda tetap menapak dan bodi mobil tidak terus memantul.', 'Pegas menyerap benturan, tetapi tanpa peredam pegas akan terus memantul naik-turun. Shock absorber mengubah energi gerak ayunan itu menjadi panas sehingga gerakan cepat berhenti, roda tetap menempel di jalan, dan mobil terasa stabil.', 'Di dalam tabung terdapat oli dan piston berlubang kecil (katup). Saat suspensi tertekan atau memanjang, piston memaksa oli melewati lubang-lubang kecil tersebut. Hambatan aliran oli inilah yang memperlambat gerakan. Banyak shock modern juga berisi gas bertekanan untuk mengurangi busa pada oli.', 'Berdiri di dekat roda, menghubungkan bagian suspensi yang bergerak (lengan atau knuckle) dengan bodi/sasis. Pada sistem MacPherson, shock menjadi bagian dari strut.', 1);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (2, 'coil-spring', 'Per Keong (Coil Spring)', 'Coil spring', 'peredam', 'Menopang berat mobil dan menyerap benturan dari permukaan jalan.', 'Per keong menahan berat kendaraan sehingga tinggi mobil tetap terjaga, lalu memendek saat roda menghantam gundukan untuk menyerap benturan sebelum sampai ke kabin.', 'Kawat baja pegas yang dililit seperti spiral akan memendek bila ditekan dan menyimpan energi. Ketika beban berkurang, energi itu dilepas sehingga per kembali memanjang. Gerakan memanjang-memendek ini kemudian diredam oleh shock absorber.', 'Di antara bodi/sasis dan bagian suspensi yang bergerak, misalnya melingkari strut (MacPherson) atau duduk di atas lengan bawah/poros belakang.', 2);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (3, 'strut-assembly', 'Strut Assembly (Rakitan Strut)', 'Strut assembly', 'peredam', 'Rakitan shock absorber, per keong, dan strut mount yang sekaligus menjadi bagian struktur suspensi MacPherson.', 'Pada suspensi MacPherson, strut bukan hanya peredam. Strut juga ikut menahan posisi roda dan menjadi poros putar roda saat dibelokkan. Karena itu strut menggabungkan tiga peran: menopang beban, meredam ayunan, dan menjadi bagian dari \'tulang\' suspensi.', 'Bagian bawah strut dibaut kuat ke knuckle (rumah roda). Bagian atas terhubung ke bodi melalui strut mount yang memiliki bantalan sehingga strut dapat berputar ketika setir dibelokkan. Per keong duduk melingkari tabung shock.', 'Berdiri tegak di belakang roda depan, dari knuckle hingga menara suspensi (strut tower) di ruang mesin.', 3);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (4, 'strut-mount', 'Strut Mount (Support Strut)', 'Strut mount / top mount', 'peredam', 'Dudukan atas strut berisi karet dan bantalan yang meredam getaran dan memungkinkan strut berputar saat setir dibelokkan.', 'Strut mount mengikat ujung atas strut ke bodi. Karetnya meredam getaran kecil agar tidak masuk ke kabin, dan bantalannya (bearing) memungkinkan strut berputar mengikuti putaran roda saat setir dibelokkan.', 'Karet tebal di dalam mount menyerap getaran frekuensi tinggi. Bearing di bawahnya berputar mulus ketika knuckle dan strut berputar terhadap sumbu kemudi.', 'Di puncak strut, dibaut ke strut tower di ruang mesin (biasanya terlihat sebagai 2–3 mur di atas menara suspensi).', 4);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (5, 'lower-control-arm', 'Lengan Bawah (Lower Control Arm)', 'Lower control arm', 'lengan', 'Lengan yang menghubungkan bagian bawah roda ke sasis dan menjaga posisi roda saat bergerak naik-turun.', 'Lower arm menahan roda agar tidak bergeser maju-mundur atau ke samping, sambil tetap memperbolehkan roda bergerak naik-turun. Lengan ini menerima gaya besar saat pengereman, akselerasi, dan menikung.', 'Sisi dalam lengan berengsel ke sasis melalui bushing karet, sisi luar terhubung ke knuckle melalui ball joint. Saat roda naik, lengan berayun pada engselnya seperti pintu yang membuka ke atas.', 'Di bagian bawah, antara rangka/subframe dan knuckle roda.', 5);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (6, 'upper-control-arm', 'Lengan Atas (Upper Control Arm)', 'Upper control arm', 'lengan', 'Lengan atas pada suspensi double wishbone yang bersama lengan bawah mengatur sudut roda saat bergerak.', 'Upper arm menahan bagian atas knuckle. Karena panjang lengan atas dan bawah berbeda, sudut kemiringan roda (camber) dapat diatur agar ban tetap menapak baik saat mobil menikung.', 'Sama seperti lengan bawah: berengsel di sasis melalui bushing dan terhubung ke knuckle melalui ball joint atas. Lengan atas biasanya lebih pendek sehingga ujung atas roda sedikit tertarik ke dalam saat suspensi tertekan.', 'Di atas roda, antara sasis dan bagian atas knuckle.', 6);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (7, 'ball-joint', 'Ball Joint (Sendi Peluru)', 'Ball joint', 'sambungan', 'Sendi berbentuk bola yang menghubungkan lengan suspensi dengan knuckle sehingga roda dapat naik-turun sekaligus dibelokkan.', 'Ball joint bekerja seperti sendi bahu manusia: memungkinkan gerakan ke berbagai arah. Roda dapat bergerak naik-turun dan berputar saat setir dibelokkan, tanpa kehilangan sambungan ke lengan.', 'Bola baja di ujung pena duduk di dalam mangkuk berlapis bahan gesek rendah dan gemuk. Karet pelindung (boot) menjaga gemuk tetap di dalam dan kotoran tetap di luar.', 'Di ujung luar lengan bawah (dan lengan atas pada double wishbone), menempel ke knuckle.', 7);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (8, 'lower-arm-bushing', 'Bushing Lengan Suspensi', 'Control arm bushing', 'sambungan', 'Karet di titik engsel lengan suspensi yang meredam getaran dan memungkinkan lengan berayun tanpa logam bergesekan dengan logam.', 'Bushing menjadi bantalan antara lengan suspensi dan sasis. Bushing menahan lengan tetap di tempatnya, menyerap getaran dan suara jalan, serta memungkinkan lengan berayun naik-turun.', 'Bushing umumnya berupa selongsong logam dalam dan luar yang diikat oleh karet. Saat lengan berayun, karet sedikit terpuntir. Karena itu bushing mempunyai sedikit kelenturan yang terkendali, bukan celah bebas.', 'Di ujung dalam lengan bawah/atas, ujung trailing arm, dan link suspensi lainnya.', 8);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (9, 'stabilizer-bar', 'Stabilizer Bar (Batang Anti-Gulung)', 'Stabilizer bar / anti-roll bar', 'stabilizer', 'Batang baja yang menghubungkan suspensi kiri dan kanan untuk mengurangi kemiringan bodi saat menikung.', 'Saat menikung, bodi mobil cenderung miring ke luar. Stabilizer bar menahan perbedaan gerakan antara roda kiri dan kanan sehingga kemiringan bodi (body roll) berkurang.', 'Batang berbentuk huruf U ini dibaut ke sasis melalui karet dudukan. Ujung-ujungnya terhubung ke suspensi kiri dan kanan melalui stabilizer link. Bila satu roda naik lebih tinggi dari yang lain, batang terpuntir dan memberikan gaya lawan. Bila kedua roda naik bersamaan, batang hampir tidak terpuntir.', 'Melintang di bawah mobil, dekat suspensi depan dan/atau belakang.', 9);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (10, 'stabilizer-link', 'Stabilizer Link (Link Stabil)', 'Stabilizer link / sway bar link', 'stabilizer', 'Batang penghubung pendek antara ujung stabilizer bar dan suspensi roda.', 'Link stabil meneruskan gerakan naik-turun roda ke ujung stabilizer bar sehingga batang dapat bekerja menahan kemiringan bodi.', 'Link biasanya memiliki sendi peluru kecil atau bushing di kedua ujung, sehingga dapat mengikuti gerakan suspensi ke berbagai arah tanpa menahan gerakan naik-turun biasa.', 'Tegak di dekat roda, dari ujung stabilizer bar ke lengan bawah atau strut.', 10);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (11, 'steering-knuckle', 'Knuckle (Rumah Roda)', 'Steering knuckle / hub carrier', 'roda', 'Komponen kokoh tempat roda, rem, dan lengan-lengan suspensi bertemu.', 'Knuckle menjadi \'pusat\' sudut roda. Hub roda dan rem terpasang di knuckle, sedangkan lengan suspensi, strut, dan tie rod mengikatnya. Pada roda depan, knuckle berputar saat setir dibelokkan.', 'Knuckle adalah benda kaku (umumnya besi tuang atau aluminium). Posisinya ditentukan oleh titik-titik sambungan ke lengan dan strut. Tie rod mendorong atau menarik lengan kemudi di knuckle sehingga roda berbelok.', 'Di balik velg, di tengah roda.', 11);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (12, 'tie-rod-end', 'Tie Rod & Tie Rod End', 'Tie rod / tie rod end', 'kemudi', 'Batang penghubung dari rack setir ke knuckle; ujungnya (tie rod end) berupa sendi peluru.', 'Tie rod meneruskan gerakan setir ke roda. Ketika setir diputar, rack bergeser dan tie rod mendorong atau menarik knuckle sehingga roda berbelok.', 'Tie rod end memiliki sendi peluru agar roda tetap dapat naik-turun sambil tetap dikendalikan. Panjang tie rod dapat disetel untuk mengatur sudut toe saat spooring.', 'Melintang dari rumah rack setir ke lengan kemudi pada knuckle, di depan atau di belakang poros roda.', 12);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (13, 'rack-and-pinion', 'Rack & Pinion (Rumah Setir)', 'Rack and pinion steering', 'kemudi', 'Mekanisme yang mengubah putaran setir menjadi gerakan menyamping untuk membelokkan roda.', 'Saat setir diputar, roda gigi kecil (pinion) memutar dan menggeser batang bergigi (rack) ke kiri atau ke kanan. Gerakan rack diteruskan ke tie rod dan roda.', 'Pinion di ujung poros setir berkaitan dengan gigi pada rack. Pada mobil modern, gerakan ini dibantu oleh power steering hidraulik atau motor listrik (EPS).', 'Melintang di bagian depan bawah, biasanya di subframe atau dekat dinding pemisah ruang mesin.', 13);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (14, 'wheel-hub', 'Hub Roda & Bearing', 'Wheel hub & bearing', 'roda', 'Tempat velg dibaut dan tempat roda berputar dengan mulus berkat bearing.', 'Hub memegang roda dan cakram rem, lalu memungkinkan roda berputar bebas dengan gesekan sekecil mungkin melalui bearing roda.', 'Bearing berisi bola atau rol baja yang berputar di dalam lintasan. Hub dibaut ke knuckle atau poros, dan velg dipasang ke baut roda di hub.', 'Di tengah roda, di antara velg dan knuckle/poros.', 14);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (15, 'trailing-arm', 'Trailing Arm (Lengan Membujur)', 'Trailing arm / trailing link', 'lengan', 'Lengan yang membujur searah panjang mobil untuk menahan roda atau poros dari gaya maju-mundur.', 'Trailing arm menahan roda atau poros agar tidak bergerak maju-mundur ketika mobil berakselerasi, mengerem, atau melewati gundukan, sambil tetap memungkinkan gerakan naik-turun.', 'Ujung depan lengan berengsel ke bodi melalui bushing. Roda atau poros berada di ujung belakang, sehingga roda bergerak naik-turun mengikuti busur ayunan lengan.', 'Membujur di bawah mobil, di depan poros roda belakang.', 15);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (16, 'torsion-beam', 'Torsion Beam (Balok Puntir)', 'Torsion beam', 'struktur', 'Balok melintang yang menyatukan dua trailing arm dan dapat sedikit terpuntir agar roda kiri-kanan bisa bergerak berbeda.', 'Torsion beam menghubungkan lengan kiri dan kanan. Balok ini cukup kaku untuk menjaga posisi roda, tetapi dapat terpuntir saat satu roda naik lebih tinggi dari roda lainnya, sehingga sekaligus bekerja seperti stabilizer bar.', 'Profil balok (sering berbentuk huruf U atau V) dirancang kuat terhadap tekukan tetapi lebih lentur terhadap puntiran. Ketika kedua roda naik bersama, seluruh rakitan berayun pada bushing depan. Ketika hanya satu roda naik, balok terpuntir.', 'Melintang di bawah bagian belakang mobil, di antara roda kiri dan kanan.', 16);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (17, 'panhard-rod', 'Lateral Rod / Panhard Rod', 'Panhard rod / lateral rod', 'lengan', 'Batang melintang yang menahan poros belakang agar tidak bergeser ke kiri-kanan.', 'Pada poros kaku, trailing link menahan gerakan maju-mundur, sedangkan lateral rod menahan poros dari gerakan menyamping saat mobil menikung.', 'Satu ujung batang berengsel ke bodi di satu sisi, ujung lainnya ke poros di sisi berlawanan. Karena ujungnya berayun mengikuti busur, poros bergeser sedikit ke samping saat naik-turun; pergeseran kecil ini memang sifat desain Panhard rod.', 'Melintang di belakang, di dekat poros roda belakang.', 17);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (18, 'multi-link-arms', 'Lengan Multi-Link', 'Multi-link control arms', 'lengan', 'Beberapa lengan (link) terpisah yang masing-masing mengatur satu arah gerakan roda.', 'Pada suspensi multi-link, tugas menahan roda dibagi ke beberapa link. Pembagian ini memudahkan perancang mengatur kenyamanan dan kestabilan secara terpisah, termasuk sudut camber dan toe saat roda bergerak.', 'Setiap link memiliki bushing atau sendi di kedua ujungnya. Kombinasi panjang dan posisi link menentukan lintasan roda. Salah satu link biasanya bertugas sebagai toe link untuk mengatur arah roda belakang.', 'Di sekitar hub carrier roda belakang, menghubungkannya ke subframe.', 18);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (19, 'axle-housing', 'Poros Kaku (Axle Housing)', 'Solid axle housing', 'struktur', 'Poros tunggal yang menyatukan roda kiri dan kanan; pada penggerak roda belakang berisi gardan dan as roda.', 'Poros kaku menyangga kedua roda dalam satu struktur yang kuat sehingga cocok untuk beban berat. Karena terhubung, gerakan satu roda akan memengaruhi roda di sisi lainnya.', 'Kedua roda berada di ujung poros yang sama. Saat satu roda naik, seluruh poros ikut miring. Link dan lateral rod menahan posisi poros, sedangkan per dan shock menopang serta meredam gerakannya.', 'Melintang di bawah bagian belakang kendaraan.', 19);
INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (20, 'wheel-assembly', 'Roda & Ban', 'Wheel & tyre', 'roda', 'Satu-satunya bagian mobil yang menyentuh jalan; semua kerja suspensi bertujuan menjaga ban tetap menapak.', 'Ban meneruskan gaya pengereman, akselerasi, dan belok ke jalan. Suspensi yang baik menjaga ban tetap menempel dan sudutnya tepat.', 'Ban bertekanan angin juga berfungsi sebagai pegas kecil. Pola keausan ban sering menjadi petunjuk awal adanya masalah suspensi atau spooring.', 'Di ujung setiap sudut suspensi.', 20);
