INSERT INTO component_education (component_id, content_type, title, body, sort_order) VALUES (3, 'failure_mode', NULL, 'Karet pelindung (boot) dan bump stopper sobek', 4);
INSERT INTO component_education (component_id, content_type, title, body, sort_order) VALUES (3, 'symptom', NULL, 'Bunyi dari ruang roda saat membelokkan setir di tempat', 1);
INSERT INTO component_education (component_id, content_type, title, body, sort_order) VALUES (3, 'symptom', NULL, 'Ayunan berlebih setelah melewati gundukan', 2);
