INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (1, 'macpherson', 'MacPherson Strut', 'MacPherson strut', 'Ringkas, ringan, dan paling umum di roda depan mobil penumpang.', 'depan', 'independen', 'Suspensi independen yang memakai strut (gabungan shock dan per) sebagai penopang atas roda, dan satu lengan bawah sebagai penopang bawah.', 'MacPherson strut adalah jenis suspensi depan yang paling banyak dipakai pada mobil penumpang. Bentuknya ringkas karena strut sekaligus menggantikan lengan atas. Ruang yang hemat ini memberi tempat lebih luas untuk mesin melintang pada mobil penggerak roda depan.', '[\"Bagian bawah roda ditahan oleh satu lengan bawah (lower arm) yang berengsel ke subframe melalui bushing, dan terhubung ke knuckle melalui ball joint.\",\"Bagian atas roda ditahan oleh strut yang dibaut ke knuckle dan bertumpu ke bodi melalui strut mount.\",\"Saat roda menghantam gundukan, lengan bawah berayun naik dan strut memendek: per keong menyerap benturan, shock meredam ayunannya.\",\"Saat setir dibelokkan, knuckle dan strut berputar bersama pada garis antara ball joint bawah dan strut mount.\"]', '[\"Roda depan sebagian besar city car, hatchback, dan sedan\",\"Roda depan banyak MPV dan SUV monokok (unibody)\",\"Mobil penggerak roda depan dengan mesin melintang\"]', '[\"Konstruksi sederhana dengan sedikit komponen\",\"Ringan dan hemat ruang\",\"Biaya produksi dan perawatan relatif rendah\"]', '[\"Perubahan sudut camber saat suspensi bergerak lebih sulit dikendalikan dibanding double wishbone\",\"Getaran jalan lebih mudah diteruskan ke bodi melalui strut tower\",\"Tinggi strut membatasi desain kap mesin yang sangat rendah\"]', 1, 'macpherson', 1);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (1, 3, NULL, 'Menggabungkan shock, per, dan mount; menjadi penopang atas roda sekaligus bagian sumbu kemudi.', NULL, 1);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (1, 1, 'Shock Absorber (di dalam strut)', 'Tabung strut berisi peredam; dibaut kaku ke knuckle.', NULL, 2);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (1, 2, NULL, 'Melingkari tabung strut dan menopang berat bagian depan mobil.', NULL, 3);
