INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (1, 5, NULL, 'Satu-satunya lengan pada sistem ini; menahan bagian bawah roda.', '1 per sisi', 5);
