INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (2, 'double-wishbone', 'Double Wishbone', 'Double wishbone', 'Dua lengan berbentuk segitiga untuk kendali sudut roda yang lebih presisi.', 'depan', 'independen', 'Suspensi independen dengan lengan atas dan lengan bawah yang masing-masing menahan knuckle melalui ball joint.', 'Double wishbone memakai dua lengan berbentuk segitiga (mirip tulang garpu ayam, \'wishbone\'). Karena posisi roda ditentukan oleh dua lengan, perancang dapat mengatur perubahan sudut roda dengan lebih leluasa. Sistem ini banyak dipakai pada roda depan pickup dan SUV berangka (ladder frame), serta mobil yang mengutamakan pengendalian.', '[\"Knuckle dijepit oleh dua lengan: lengan atas (upper arm) dan lengan bawah (lower arm), masing-masing melalui ball joint.\",\"Lengan atas biasanya lebih pendek dari lengan bawah, sehingga saat roda naik bagian atas roda sedikit tertarik ke dalam (camber negatif) dan ban tetap menapak baik ketika bodi miring.\",\"Per keong dan shock absorber bertumpu pada lengan bawah dan sasis; keduanya tidak ikut menahan posisi roda.\",\"Saat setir dibelokkan, knuckle berputar pada garis antara ball joint atas dan bawah.\"]', '[\"Roda depan banyak pickup dan SUV berangka (ladder frame)\",\"Mobil sport dan beberapa sedan premium\",\"Kendaraan yang memerlukan daya angkut dan pengendalian baik\"]', '[\"Kontrol sudut camber yang baik sehingga cengkeraman ban lebih konsisten\",\"Shock absorber tidak menahan gaya samping sehingga bekerja lebih mulus\",\"Kuat untuk beban berat\"]', '[\"Lebih banyak komponen sehingga biaya lebih tinggi\",\"Memerlukan ruang lebih besar\",\"Penyetelan dan perawatan lebih kompleks\"]', 1, 'double-wishbone', 2);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (2, 6, NULL, 'Menahan bagian atas knuckle; lebih pendek dari lengan bawah.', '1 per sisi', 1);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (2, 5, NULL, 'Menahan bagian bawah knuckle dan menjadi dudukan bawah per/shock.', '1 per sisi', 2);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (2, 7, 'Ball Joint Atas & Bawah', 'Dua ball joint menghubungkan kedua lengan ke knuckle.', '2 per sisi', 3);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (2, 8, 'Bushing Lengan Atas & Bawah', 'Engsel karet kedua lengan ke sasis.', NULL, 4);
