INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (3, 'torsion-beam', 'Torsion Beam', 'Torsion beam axle', 'Suspensi belakang sederhana dan kokoh yang hemat ruang.', 'belakang', 'semi-independen', 'Dua trailing arm yang disatukan oleh balok melintang yang dapat terpuntir.', 'Torsion beam adalah suspensi belakang semi-independen yang sangat umum pada mobil penggerak roda depan. Konstruksinya sederhana dan ringkas sehingga ruang bagasi dan lantai kabin bisa lebih lega.', '[\"Dua trailing arm berengsel ke bodi melalui bushing di bagian depannya; roda terpasang di ujung belakang lengan.\",\"Kedua lengan disatukan oleh balok melintang (torsion beam).\",\"Bila kedua roda naik bersama (misalnya melewati polisi tidur), seluruh rakitan berayun pada bushing depan.\",\"Bila hanya satu roda naik, balok terpuntir. Puntiran ini memberi efek seperti stabilizer bar.\"]', '[\"Roda belakang banyak city car dan hatchback penggerak roda depan\",\"Roda belakang banyak MPV kecil dan LCGC\",\"Sebagian crossover kecil\"]', '[\"Sederhana, ringan, dan murah\",\"Hemat ruang sehingga bagasi lebih luas\",\"Perawatan relatif mudah; titik aus utama ada di bushing\"]', '[\"Roda kiri-kanan saling memengaruhi sehingga kenyamanan di jalan rusak terbatas\",\"Kebebasan pengaturan sudut roda lebih sedikit dibanding multi-link\",\"Kurang cocok untuk roda belakang penggerak\"]', 0, 'torsion-beam', 3);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (3, 16, NULL, 'Balok melintang yang menyatukan kedua trailing arm dan bekerja sebagai anti-roll.', NULL, 1);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (3, 15, NULL, 'Lengan membujur yang membawa roda dan berayun pada bushing depan.', '1 per sisi', 2);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (3, 8, 'Bushing Trailing Arm', 'Engsel karet seluruh rakitan ke bodi; titik aus paling umum.', '1 per sisi', 3);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (3, 2, NULL, 'Duduk di atas lengan dan menopang berat bagian belakang.', NULL, 4);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (3, 1, NULL, 'Terpasang terpisah dari per, di belakang poros roda.', NULL, 5);
