INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (4, 'multi-link', 'Multi-Link', 'Multi-link', 'Beberapa link terpisah untuk keseimbangan kenyamanan dan kestabilan.', 'belakang', 'independen', 'Suspensi independen yang membagi tugas menahan roda ke beberapa link (umumnya empat atau lima).', 'Multi-link adalah pengembangan dari double wishbone. Alih-alih dua lengan segitiga, roda ditahan oleh beberapa link lurus yang masing-masing mengatur arah gerakan tertentu. Hasilnya, perancang dapat menyetel kenyamanan dan kestabilan dengan lebih leluasa. Model di aplikasi ini adalah contoh tata letak lima link yang disederhanakan.', '[\"Hub carrier (rumah roda belakang) ditahan oleh beberapa link: dua link atas, lengan bawah tempat per, toe link, dan trailing link.\",\"Link-link lateral menentukan posisi samping dan sudut camber; toe link menjaga arah roda; trailing link menahan gaya maju-mundur.\",\"Per keong biasanya duduk di lengan bawah, sedangkan shock absorber terpasang terpisah.\",\"Stabilizer bar menghubungkan suspensi kiri dan kanan.\"]', '[\"Roda belakang banyak sedan menengah ke atas\",\"Roda belakang banyak SUV dan crossover modern\",\"Mobil berpenggerak roda belakang atau empat roda\"]', '[\"Keseimbangan kenyamanan dan pengendalian yang sangat baik\",\"Perubahan sudut roda dapat dirancang dengan teliti\",\"Getaran dan suara jalan dapat diisolasi dengan baik\"]', '[\"Banyak komponen dan bushing sehingga biaya lebih tinggi\",\"Pemeriksaan dan spooring lebih rumit\",\"Memerlukan ruang lebih besar dibanding torsion beam\"]', 0, 'multi-link', 4);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (4, 18, 'Link Atas & Toe Link', 'Dua link atas dan toe link mengatur camber serta arah roda.', '3 per sisi', 1);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (4, 5, 'Lengan Bawah (Spring Link)', 'Lengan bawah tempat per bertumpu.', NULL, 2);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (4, 15, 'Trailing Link', 'Menahan gaya maju-mundur hub carrier.', NULL, 3);
