INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (4, 11, 'Hub Carrier (Knuckle Belakang)', 'Rumah roda belakang tempat semua link bertemu; tidak dibelokkan oleh setir.', NULL, 5);
