INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (5, 'rigid-axle', 'Rigid Axle (Poros Kaku)', 'Rigid / solid axle', 'Satu poros kuat untuk beban berat dan medan berat.', 'belakang', 'dependen', 'Kedua roda dipasang pada satu poros kaku; contoh ini memakai per keong, empat link membujur, dan lateral rod.', 'Pada poros kaku (solid axle), roda kiri dan kanan berada di satu poros. Sistem ini sangat kuat dan tahan beban, sehingga banyak dipakai pada roda belakang pickup, SUV berangka, dan kendaraan niaga. Variasinya ada yang memakai per daun (leaf spring) dan ada yang memakai per keong dengan link; model ini menampilkan versi per keong dengan link dan lateral rod.', '[\"Kedua roda terpasang di ujung rumah poros (axle housing). Pada penggerak roda belakang, poros berisi gardan dan as roda.\",\"Empat link membujur (dua bawah, dua atas) menahan poros dari gerakan maju-mundur dan puntiran saat akselerasi/pengereman.\",\"Lateral rod (Panhard rod) menahan poros dari gerakan menyamping.\",\"Saat satu roda naik, seluruh poros ikut miring sehingga sudut roda di sisi lain juga berubah.\"]', '[\"Roda belakang banyak pickup dan SUV berangka\",\"Roda belakang beberapa MPV penggerak roda belakang\",\"Kendaraan niaga, truk ringan, dan kendaraan off-road\"]', '[\"Sangat kuat dan tahan beban berat\",\"Konstruksi tahan banting, cocok untuk medan berat\",\"Ground clearance relatif konstan saat membawa beban\"]', '[\"Kenyamanan di jalan bergelombang lebih rendah\",\"Bobot tak berpegas (unsprung mass) besar\",\"Gerakan satu roda memengaruhi roda lainnya\"]', 0, 'rigid-axle', 5);
INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (5, 19, NULL, 'Poros tunggal yang membawa kedua roda.', NULL, 1);
