INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (1, 'bushing-worn', 8, 'Bushing Lengan Aus atau Sobek', 'Bushing aus', 'sedang', 'Karet bushing utuh dan menahan lengan tetap di posisinya. Lengan hanya berayun naik-turun dengan mulus.', 'Karet retak atau sobek sehingga lengan dapat bergeser maju-mundur dan ke samping di titik engselnya, terutama saat melewati gundukan atau mengerem.', 'Karet bushing menua karena panas, beban berulang, dan kontaminasi oli. Ketika karet retak, celah muncul di antara selongsong logam sehingga lengan tidak lagi tertahan dengan rapat.', '[\"Bunyi \'gluduk\' atau \'kletak\' saat melewati jalan rusak\",\"Setir bergetar atau mobil sedikit menarik saat mengerem\",\"Mobil terasa kurang stabil di kecepatan tinggi\",\"Keausan ban tidak rata\"]', '[\"Sudut roda dapat berubah-ubah saat berkendara sehingga respons kendaraan kurang dapat diprediksi\",\"Beban berlebih berpindah ke ball joint dan komponen lain\"]', '[\"Pemeriksaan visual retak dan sobek pada karet\",\"Pemeriksaan gerakan lengan menggunakan tuas saat mobil diangkat\",\"Uji jalan untuk memastikan sumber bunyi\",\"Spooring setelah penggantian bushing\"]', 'bushing-play', '{\"playMm\":6,\"visualExaggeration\":3}', 'bump', 1);
INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (2, 'ball-joint-play', 7, 'Ball Joint dengan Kelonggaran Berlebih', 'Ball joint longgar', 'tinggi', 'Bola duduk rapat di mangkuknya. Knuckle bergerak tepat mengikuti ujung lengan tanpa celah.', 'Bola dan mangkuk aus sehingga ada celah. Knuckle dapat bergeser relatif terhadap lengan dan menimbulkan ketukan setiap kali arah gaya berubah.', 'Boot yang sobek membuat gemuk hilang dan kotoran masuk. Gesekan yang meningkat mengikis permukaan bola dan mangkuk sehingga muncul kelonggaran yang terus membesar.', '[\"Bunyi \'tok-tok\' saat melewati gundukan atau saat berbelok\",\"Setir terasa longgar atau mobil mengambang\",\"Keausan ban di satu sisi\"]', '[\"Pada kondisi parah ball joint dapat terlepas sehingga roda kehilangan posisi\",\"Ini adalah komponen keselamatan: hentikan pemakaian berat dan segera periksakan bila dicurigai\"]', '[\"Roda diangkat lalu digoyang atas-bawah (posisi jam 12 dan 6)\",\"Pengamatan langsung gerakan pada ball joint menggunakan tuas\",\"Pemeriksaan kondisi boot\"]', 'ball-joint-play', '{\"playMm\":5,\"visualExaggeration\":3}', 'bump', 2);
INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (3, 'weak-shock', 1, 'Shock Absorber Lemah', 'Shock lemah', 'tinggi', 'Setelah melewati gundukan, suspensi kembali ke posisi normal dalam sekitar satu kali ayunan.', 'Daya redam berkurang sehingga suspensi terus mengayun beberapa kali sebelum berhenti, dan roda sempat kehilangan tekanan ke jalan.', 'Seal yang bocor atau katup yang aus membuat oli mengalir terlalu mudah di dalam shock. Hambatan berkurang sehingga energi ayunan tidak teredam dengan baik.', '[\"Mobil mengayun berulang setelah melewati polisi tidur\",\"Bodi terasa mengapung di kecepatan tinggi\",\"Hidung mobil menukik saat mengerem\",\"Rembesan oli pada tabung shock\",\"Keausan ban bergelombang\"]', '[\"Roda yang memantul kurang menapak sehingga jarak pengereman dapat bertambah\",\"Stabilitas saat menikung dan manuver darurat menurun\"]', '[\"Pemeriksaan rembesan oli dan kondisi seal\",\"Uji tekan bodi dan uji jalan\",\"Pengujian dengan alat penguji suspensi bila tersedia\",\"Penggantian sebaiknya berpasangan kiri-kanan\"]', 'weak-damper', '{\"normalDampingRatio\":0.4,\"damagedDampingRatio\":0.07}', 'bump', 3);
INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (4, 'stabilizer-link-loose', 10, 'Stabilizer Link Rusak', 'Link stabil rusak', 'sedang', 'Link meneruskan gerakan roda ke ujung stabilizer bar tanpa celah, sehingga batang terpuntir saat roda kiri-kanan bergerak berbeda.', 'Sendi di ujung link longgar. Gerakan roda tidak langsung diteruskan ke stabilizer bar sehingga batang terlambat bekerja dan muncul ketukan.', 'Sendi peluru kecil di ujung link aus atau boot-nya sobek. Celah membuat link bergerak bebas sesaat sebelum menahan beban.', '[\"Bunyi \'tok-tok\' kecil saat pelan di jalan bergelombang\",\"Bodi lebih limbung saat menikung\"]', '[\"Efek anti-gulung berkurang sehingga stabilitas saat manuver mendadak menurun\",\"Link yang patah dapat mengganggu komponen di sekitarnya\"]', '[\"Menggoyang link dengan tangan atau tuas\",\"Pemeriksaan boot dan kedua ujung sendi\"]', 'stabilizer-link-loose', '{\"playMm\":10,\"visualExaggeration\":2}', 'rough', 4);
INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (5, 'strut-mount-worn', 4, 'Strut Mount Aus', 'Strut mount aus', 'sedang', 'Karet mount meredam getaran dan bearing berputar halus saat setir dibelokkan. Ujung atas strut tetap di posisinya.', 'Karet amblas atau retak sehingga ujung atas strut dapat bergeser, dan bearing yang aus membuat putaran strut tersendat.', 'Karet menua dan bearing kehilangan pelumas atau berkarat. Strut tidak lagi tertahan rapat di strut tower.', '[\"Bunyi \'krek\' atau \'tok\' saat memutar setir di tempat\",\"Dentuman dari atas roda di jalan rusak\",\"Setir terasa kasar atau berat\"]', '[\"Posisi atas strut yang bergeser dapat mengubah sudut roda\",\"Getaran dan beban kejut lebih banyak diteruskan ke komponen lain\"]', '[\"Pemeriksaan karet mount dari ruang mesin\",\"Merasakan gerakan di atas strut saat setir diputar\",\"Mendengarkan bunyi saat setir diputar penuh\"]', 'strut-mount-worn', '{\"sagMm\":8,\"playMm\":5,\"visualExaggeration\":3}', 'steer', 5);
INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (6, 'tie-rod-end-damaged', 12, 'Tie Rod End Rusak', 'Tie rod end rusak', 'tinggi', 'Tie rod meneruskan gerakan rack ke knuckle tanpa jeda. Roda berbelok tepat sesuai putaran setir.', 'Sendi tie rod end longgar sehingga ada jeda sebelum roda merespons dan roda dapat bergoyang sedikit ke kiri-kanan (perubahan toe) saat melaju.', 'Sendi peluru di ujung tie rod aus, biasanya diawali boot yang sobek. Kelonggaran membuat arah roda tidak lagi ditahan dengan tepat.', '[\"Setir terasa longgar atau kurang responsif\",\"Bunyi ketukan saat berbelok pelan\",\"Ban aus di bagian tepi\",\"Setir bergetar\"]', '[\"Kendali arah roda berkurang; pada kasus parah sambungan dapat terlepas\",\"Ini adalah komponen keselamatan yang perlu diperiksa segera bila dicurigai rusak\"]', '[\"Roda diangkat lalu digoyang kiri-kanan (posisi jam 3 dan 9)\",\"Pengamatan langsung gerakan pada sendi tie rod end\",\"Spooring wajib setelah penggantian\"]', 'tie-rod-play', '{\"toeWobbleDeg\":1.2,\"visualExaggeration\":3}', 'steer', 6);
